import os
import sys
import json
import uuid
import logging
import datetime
import bcrypt

import jwt
import redis
from flask import Flask, request, jsonify

# Setup logging
os.makedirs("/app/logs", exist_ok=True)
logging.basicConfig(
    filename="/app/logs/app.log",
    level=logging.INFO,
    format="%(asctime)s %(levelname)s %(message)s"
)
logger = logging.getLogger(__name__)

app = Flask(__name__)

# Redis connection
redis_client = redis.Redis(host="localhost", port=6379, decode_responses=True)

# Paths
KEYS_DIR = "/app/keys"
PRIVATE_KEY_PATH = os.path.join(KEYS_DIR, "private.pem")
PUBLIC_KEY_PATH = os.path.join(KEYS_DIR, "public.pem")

# Default user credentials
DEFAULT_USER = {"username": "admin", "password_hash": bcrypt.hashpw(b"password123", bcrypt.gensalt()).decode()}
USERS_DB_PATH = "/app/users.json"


def ensure_keys():
    """Generate RSA key pair if not exists."""
    os.makedirs(KEYS_DIR, exist_ok=True)
    if not os.path.exists(PRIVATE_KEY_PATH) or not os.path.exists(PUBLIC_KEY_PATH):
        from cryptography.hazmat.primitives import rsa
        from cryptography.hazmat.primitives import serialization
        private_key = rsa.generate_private_key(public_exponent=65537, key_size=2048)
        private_pem = private_key.private_bytes(
            encoding=serialization.Encoding.PEM,
            format=serialization.PrivateFormat.PKCS8,
            encryption_algorithm=serialization.NoEncryption()
        )
        public_pem = private_key.public_key().public_bytes(
            encoding=serialization.Encoding.PEM,
            format=serialization.PublicFormat.SubjectPublicKeyInfo
        )
        with open(PRIVATE_KEY_PATH, "wb") as f:
            f.write(private_pem)
        with open(PUBLIC_KEY_PATH, "wb") as f:
            f.write(public_pem)
        logger.info("RSA key pair generated")


def ensure_users_db():
    """Create users DB if not exists."""
    if not os.path.exists(USERS_DB_PATH):
        with open(USERS_DB_PATH, "w") as f:
            json.dump([DEFAULT_USER], f)
        logger.info("Default user created")


def get_private_key():
    with open(PRIVATE_KEY_PATH, "rb") as f:
        return f.read()


def get_public_key():
    with open(PUBLIC_KEY_PATH, "rb") as f:
        return f.read()


def create_token(username, token_type="access"):
    """Create a JWT token."""
    now = datetime.datetime.utcnow()
    if token_type == "access":
        exp = now + datetime.timedelta(minutes=15)
    else:
        exp = now + datetime.timedelta(days=7)

    payload = {
        "iss": "auth-service",
        "sub": username,
        "iat": now,
        "exp": exp,
        "jti": str(uuid.uuid4()),
        "type": token_type
    }
    token = jwt.encode(payload, get_private_key(), algorithm="RS256")
    return token, payload["exp"], payload["jti"]


def decode_token(token):
    """Decode and verify a JWT token."""
    return jwt.decode(token, get_public_key(), algorithms=["RS256"])


def is_blacklisted(jti):
    """Check if a token JTI is in the blacklist."""
    return redis_client.exists(f"blacklist:{jti}") > 0


def blacklist_token(jti, exp):
    """Add a token JTI to the blacklist with TTL."""
    ttl = max(1, int(exp - datetime.datetime.utcnow().timestamp()))
    redis_client.setex(f"blacklist:{jti}", ttl, "revoked")
    logger.info(f"Token {jti} blacklisted with TTL {ttl}s")


@app.route("/auth/login", methods=["POST"])
def login():
    """Login and get access/refresh tokens."""
    try:
        data = request.get_json()
        if not data or "username" not in data or "password" not in data:
            return jsonify({"error": "Missing username or password"}), 400

        username = data["username"]
        password = data["password"]

        # Load users
        with open(USERS_DB_PATH) as f:
            users = json.load(f)

        user = None
        for u in users:
            if u["username"] == username:
                user = u
                break

        if not user or not bcrypt.checkpw(password.encode(), user["password_hash"].encode()):
            logger.warning(f"Failed login attempt for {username}")
            return jsonify({"error": "Invalid credentials"}), 401

        access_token, access_exp, access_jti = create_token(username, "access")
        refresh_token, refresh_exp, refresh_jti = create_token(username, "refresh")

        logger.info(f"User {username} logged in successfully")
        return jsonify({
            "access_token": access_token,
            "refresh_token": refresh_token,
            "access_expires_in": 900,
            "refresh_expires_in": 604800
        }), 200
    except Exception as e:
        logger.error(f"Login error: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/auth/refresh", methods=["POST"])
def refresh():
    """Refresh access token using refresh token."""
    try:
        data = request.get_json()
        if not data or "refresh_token" not in data:
            return jsonify({"error": "Missing refresh token"}), 400

        token = data["refresh_token"]
        payload = decode_token(token)

        if payload.get("type") != "refresh":
            return jsonify({"error": "Invalid token type"}), 401

        if is_blacklisted(payload["jti"]):
            return jsonify({"error": "Token has been revoked"}), 403

        username = payload["sub"]
        access_token, access_exp, access_jti = create_token(username, "access")

        logger.info(f"Access token refreshed for {username}")
        return jsonify({
            "access_token": access_token,
            "access_expires_in": 900
        }), 200
    except jwt.ExpiredSignatureError:
        return jsonify({"error": "Token has expired"}), 401
    except jwt.InvalidTokenError as e:
        logger.error(f"Invalid token: {e}")
        return jsonify({"error": "Invalid token"}), 401
    except Exception as e:
        logger.error(f"Refresh error: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/auth/revoke", methods=["POST"])
def revoke():
    """Revoke a token by adding it to the blacklist."""
    try:
        data = request.get_json()
        if not data or "token" not in data:
            return jsonify({"error": "Missing token"}), 400

        token = data["token"]
        payload = decode_token(token)

        if is_blacklisted(payload["jti"]):
            return jsonify({"error": "Token already revoked"}), 403

        blacklist_token(payload["jti"], payload["exp"])
        logger.info(f"Token revoked: {payload['jti']}")
        return jsonify({"message": "Token revoked"}), 200
    except jwt.ExpiredSignatureError:
        return jsonify({"error": "Token has expired"}), 401
    except jwt.InvalidTokenError as e:
        logger.error(f"Invalid token: {e}")
        return jsonify({"error": "Invalid token"}), 401
    except Exception as e:
        logger.error(f"Revoke error: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/auth/validate", methods=["GET"])
def validate():
    """Validate a token and check blacklist/expiration."""
    try:
        auth_header = request.headers.get("Authorization", "")
        if not auth_header.startswith("Bearer "):
            return jsonify({"error": "Missing or invalid authorization header"}), 401

        token = auth_header.split(" ", 1)[1]
        payload = decode_token(token)

        if is_blacklisted(payload["jti"]):
            return jsonify({"valid": False, "error": "Token has been revoked"}), 403

        return jsonify({
            "valid": True,
            "payload": payload
        }), 200
    except jwt.ExpiredSignatureError:
        return jsonify({"valid": False, "error": "Token has expired"}), 401
    except jwt.InvalidTokenError as e:
        logger.error(f"Invalid token: {e}")
        return jsonify({"valid": False, "error": "Invalid token"}), 401
    except Exception as e:
        logger.error(f"Validate error: {e}")
        return jsonify({"valid": False, "error": str(e)}), 500


if __name__ == "__main__":
    ensure_keys()
    ensure_users_db()
    app.run(host="0.0.0.0", port=5000)
